-module(generators).
f(L,M,B) -> {
  [X || X <- L],
  #{X => X || X <- L},
  << <<X>> || X <- L >>,
  [X || X <:- L],
  #{X => X || X <:- L},
  << <<X>> || X <:- L >>,
  [X || <<X>> <= B],
  #{X => X || <<X>> <= B},
  << <<X>> || <<X>> <= B >>,
  [X || <<X>> <:= B],
  #{X => X || <<X>> <:= B},
  << <<X>> || <<X>> <:= B >>,
  [X || K := X <- M],
  #{X => X || K := X <- M},
  << <<X>> || K := X <- M >>,
  [X || K := X <:- M],
  #{X => X || K := X <:- M},
  << <<X>> || K := X <:- M >>
}.
